package adapter

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
	"reflect"

	mp4 "github.com/abema/go-mp4"

	"mediad/timeline"
)

// MP4Adapter parses a minimal single-track ISOBMFF sample file generated by
// WriteMP4: it reads mdhd/stts/stsz/stco/stss, reconstructs per-sample times,
// validates payloads against mdat and preserves unknown boxes (e.g. emsg).
type MP4Adapter struct{}

func (MP4Adapter) Name() string     { return "mp4" }
func (MP4Adapter) Version() Version { return Version{Major: 1, Minor: 0} }

func (MP4Adapter) Parse(r io.Reader, opts Options) (*ParseResult, error) {
	raw, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	rs := bytes.NewReader(raw)
	// Truncation: the first top-level box header must be fully readable and
	// every declared box must fit inside the available bytes.
	mdhd, stts, stsz, stco, stss, err := readIndexBoxes(rs)
	if err != nil {
		return nil, fmt.Errorf("mp4: %w", err)
	}
	if mdhd.Timescale == 0 {
		return nil, fmt.Errorf("mp4: illegal timescale 0")
	}
	mdatData, mdatPayloadStart, emsgs, err := readTopLevel(rs)
	if err != nil {
		return nil, fmt.Errorf("mp4: %w", err)
	}
	samples, err := expandSamples(stts, stsz, stco, stss, mdatData, mdatPayloadStart)
	if err != nil {
		return nil, fmt.Errorf("mp4: %w", err)
	}
	trackID := opts.TrackID
	if trackID == 0 {
		trackID = 1
	}
	tr := timeline.Track{ID: trackID, Kind: timeline.KindVideo, Clock: timeline.Clock{
		Timescale: int64(mdhd.Timescale), OriginNS: opts.OriginNS, MaxDriftNS: opts.MaxDriftNS}}
	res := &ParseResult{}
	var tick uint64
	for i, s := range samples {
		// stts deltas must be non-zero; a zero delta is an illegal length.
		if s.delta == 0 {
			return nil, fmt.Errorf("mp4: illegal zero stts delta at sample %d", i)
		}
		if i > 0 && tick < uint64(samples[i-1].delta) {
			return nil, fmt.Errorf("mp4: out-of-order sample time at sample %d", i)
		}
		payload := append([]byte(nil), mdatData[s.offset:s.offset+s.size]...)
		ev := timeline.Event{TrackID: trackID, Kind: timeline.KindVideo, Tick: int64(tick),
			Seq: int64(i), Size: int(s.size), Keyframe: s.keyframe, Payload: payload}
		if len(payload) >= 4 && binary.BigEndian.Uint32(payload[:4]) != sampleMagic {
			ev.Corrupt = true
		}
		tr.Events = append(tr.Events, ev)
		tick += uint64(s.delta)
	}
	res.Tracks = []timeline.Track{tr}
	for _, e := range emsgs {
		res.Unknown = append(res.Unknown, timeline.UnknownMeta{MetaType: "emsg", Raw: e})
	}
	return res, nil
}

type rawSample struct {
	delta, size, offset uint32
	keyframe            bool
}

func readIndexBoxes(rs io.ReadSeeker) (*mp4.Mdhd, *mp4.Stts, *mp4.Stsz, *mp4.Stco, *mp4.Stss, error) {
	paths := []mp4.BoxPath{
		{mp4.BoxTypeMoov(), mp4.BoxTypeTrak(), mp4.BoxTypeMdia(), mp4.BoxTypeMdhd()},
		{mp4.BoxTypeMoov(), mp4.BoxTypeTrak(), mp4.BoxTypeMdia(), mp4.BoxTypeMinf(), mp4.BoxTypeStbl(), mp4.BoxTypeStts()},
		{mp4.BoxTypeMoov(), mp4.BoxTypeTrak(), mp4.BoxTypeMdia(), mp4.BoxTypeMinf(), mp4.BoxTypeStbl(), mp4.BoxTypeStsz()},
		{mp4.BoxTypeMoov(), mp4.BoxTypeTrak(), mp4.BoxTypeMdia(), mp4.BoxTypeMinf(), mp4.BoxTypeStbl(), mp4.BoxTypeStco()},
		{mp4.BoxTypeMoov(), mp4.BoxTypeTrak(), mp4.BoxTypeMdia(), mp4.BoxTypeMinf(), mp4.BoxTypeStbl(), mp4.BoxTypeStss()},
	}
	found := map[reflect.Type]*mp4.BoxInfoWithPayload{}
	for _, p := range paths {
		boxes, err := mp4.ExtractBoxesWithPayload(rs, nil, []mp4.BoxPath{p})
		if err != nil {
			return nil, nil, nil, nil, nil, err
		}
		if len(boxes) == 0 {
			if p[len(p)-1] == mp4.BoxTypeStss() {
				continue // keyframe table is optional
			}
			return nil, nil, nil, nil, nil, fmt.Errorf("missing box %s", p[len(p)-1])
		}
		found[reflect.TypeOf(boxes[0].Payload)] = boxes[0]
	}
	get := func(t reflect.Type) *mp4.BoxInfoWithPayload { return found[t] }
	mdhd := get(reflect.TypeOf(&mp4.Mdhd{})).Payload.(*mp4.Mdhd)
	stts := get(reflect.TypeOf(&mp4.Stts{})).Payload.(*mp4.Stts)
	stsz := get(reflect.TypeOf(&mp4.Stsz{})).Payload.(*mp4.Stsz)
	stco := get(reflect.TypeOf(&mp4.Stco{})).Payload.(*mp4.Stco)
	var stss *mp4.Stss
	if b := get(reflect.TypeOf(&mp4.Stss{})); b != nil {
		stss = b.Payload.(*mp4.Stss)
	}
	return mdhd, stts, stsz, stco, stss, nil
}

func readTopLevel(rs io.ReadSeeker) (mdat []byte, payloadStart uint64, emsgs [][]byte, err error) {
	if _, err := rs.Seek(0, io.SeekStart); err != nil {
		return nil, 0, nil, err
	}
	fileSize, err := rs.Seek(0, io.SeekEnd)
	if err != nil {
		return nil, 0, nil, err
	}
	if _, err := rs.Seek(0, io.SeekStart); err != nil {
		return nil, 0, nil, err
	}
	for {
		bi, err := mp4.ReadBoxInfo(rs)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, 0, nil, err
		}
		if bi.Offset+bi.Size > uint64(fileSize) {
			return nil, 0, nil, fmt.Errorf("truncated box %s: declares %d bytes at offset %d, file has %d",
				bi.Type, bi.Size, bi.Offset, fileSize)
		}
		switch bi.Type {
		case mp4.BoxTypeMdat():
			payloadStart = bi.Offset + bi.HeaderSize
			buf := make([]byte, bi.Size-bi.HeaderSize)
			if _, err := io.ReadFull(rs, buf); err != nil {
				return nil, 0, nil, fmt.Errorf("truncated mdat payload: %w", err)
			}
			mdat = buf
		default:
			buf := make([]byte, bi.Size-bi.HeaderSize)
			if _, err := io.ReadFull(rs, buf); err != nil {
				return nil, 0, nil, fmt.Errorf("truncated %s payload: %w", bi.Type, err)
			}
			if bi.Type == mp4.BoxTypeEmsg() {
				emsgs = append(emsgs, buf)
			}
		}
	}
	if mdat == nil {
		return nil, 0, nil, fmt.Errorf("missing mdat box")
	}
	return mdat, payloadStart, emsgs, nil
}

func expandSamples(stts *mp4.Stts, stsz *mp4.Stsz, stco *mp4.Stco, stss *mp4.Stss, mdat []byte, mdatPayloadStart uint64) ([]rawSample, error) {
	var deltas []uint32
	var total uint32
	for _, e := range stts.Entries {
		if e.SampleCount == 0 {
			return nil, fmt.Errorf("illegal stts sample count 0")
		}
		for j := uint32(0); j < e.SampleCount; j++ {
			deltas = append(deltas, e.SampleDelta)
		}
		total += e.SampleCount
	}
	var sizes []uint32
	if stsz.SampleSize != 0 {
		for j := uint32(0); j < stsz.SampleCount; j++ {
			sizes = append(sizes, stsz.SampleSize)
		}
	} else {
		sizes = append(sizes, stsz.EntrySize...)
	}
	if len(deltas) != len(sizes) || uint32(len(sizes)) != stsz.SampleCount {
		return nil, fmt.Errorf("illegal length: stts=%d stsz=%d", len(deltas), len(sizes))
	}
	keySet := map[uint32]bool{}
	if stss != nil {
		for _, n := range stss.SampleNumber {
			if n == 0 || n > total {
				return nil, fmt.Errorf("illegal stss sample number %d", n)
			}
			keySet[n] = true
		}
	}
	out := make([]rawSample, 0, total)
	chunk, inChunk, cursor := 0, uint32(0), uint32(0)
	for i := uint32(0); i < total; i++ {
		if chunk >= len(stco.ChunkOffset) {
			return nil, fmt.Errorf("illegal length: not enough chunk offsets for %d samples", total)
		}
		absOff := stco.ChunkOffset[chunk] + cursor
		if uint64(absOff) < mdatPayloadStart {
			return nil, fmt.Errorf("illegal stco offset %d before mdat payload %d", absOff, mdatPayloadStart)
		}
		relOff := uint64(absOff) - mdatPayloadStart
		if relOff+uint64(sizes[i]) > uint64(len(mdat)) {
			return nil, fmt.Errorf("truncated mdat: sample %d extends past payload", i)
		}
		out = append(out, rawSample{delta: deltas[i], size: sizes[i], offset: uint32(relOff), keyframe: keySet[i+1] || (stss == nil && i == 0)})
		cursor += sizes[i]
		inChunk++
		// One sample per chunk in the generated fixtures; wrap on boundary.
		if inChunk >= 1 {
			chunk++
			inChunk, cursor = 0, 0
		}
	}
	return out, nil
}
